        <div id="return-xml-ewt" hidden><div class="return-review-grid"><label>1st-month remittance (₱)<input name="xml_remittance_month1" value="0.00" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?"></label><label>2nd-month remittance (₱)<input name="xml_remittance_month2" value="0.00" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?"></label><label>Prior-quarter over-remittance, same year (₱)<input name="xml_prior_overremittance" value="0.00" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?"></label></div><label class="return-note">If over-remitted<select name="xml_overpayment_action"><option value="">Choose when applicable</option><option value="refund">Refund</option><option value="certificate">Tax credit certificate</option><option value="carry_over">Carry over within the same calendar year</option></select></label></div>
